const pendOf=id=>S.reqList.find(r=>r.slot_id===id&&r.status==='pending');
const slotById=id=>slotsAll.find(s=>s.id===id);
async function pollReqs(){const{data,error}=await SB.from('turnos_requests').select('*').order('created_at',{ascending:false}).limit(300);if(error)return;const g=JSON.stringify(data);if(g===S.reqSig)return;S.reqSig=g;S.reqList=data;render()}
async function pollNotifs(){const{data,error}=await SB.from('turnos_notifications').select('id,kind,payload,created_at,read_at').order('created_at',{ascending:false}).limit(60);if(error)return;const g=JSON.stringify(data);if(g===S.notSig)return;S.notSig=g;S.notifs=data;renderBell()}
async function pollMembers(){if(ME.role==='employee')return;const{data,error}=await SB.from('turnos_members').select('*').order('email');if(error)return;const g=JSON.stringify(data);if(g===S.memSig)return;S.memSig=g;S.members=data;render()}
function startPortal(){$('acct-mail').textContent=ME.email;$('logout').onclick=()=>window.__T.signOut();$('bell').onclick=openBell;
 pollReqs();pollNotifs();pollMembers();pollPhone();setInterval(()=>{if(!document.hidden){pollReqs();pollNotifs();pollMembers();pollPhone()}},20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){pollReqs();pollNotifs();pollPhone()}})}
/* працівник не змінює графік напряму: заявка йде менеджеру */
function claim(s,person,force){if(S.as){toast(tr('t_preview'));return}if(isMgrOf(s.pk))return _claim(s,person,force);return sendReq('take',s)}
async function release(s){if(S.as){toast(tr('t_preview'));return}if(isMgrOf(s.pk))return _release(s);return sendReq('drop',s)}
async function sendReq(kind,s){try{await rpc('turnos_request',{p_kind:kind,p_slot:s.id,p_note:null});toast(tr('req_sent'));await pollReqs();KICK()}catch(e){toast(rpcErr(e))}}
async function cancelReq(id){try{await rpc('turnos_cancel_request',{p_id:id});toast(tr('req_cancelled'));await pollReqs()}catch(e){toast(rpcErr(e))}}
async function decide(id,ok,reason){if(S.as){toast(tr('t_preview'));return}try{await rpc('turnos_decide',{p_id:id,p_approve:ok,p_reason:reason||null});toast(tr(ok?'req_ok':'req_no'));await pollReqs();KICK()}catch(e){toast(rpcErr(e));pollReqs()}}
