 const av=pl.filter(p=>p.av);if(av.length)chip('🥽 Avatar '+av.map(p=>p.t||'?').join(', '),true);const cnt={};pl.filter(p=>!p.av).forEach(p=>{cnt[p.tipo]=(cnt[p.tipo]||0)+1});
