 if(canDecide&&r.kind==='take'){const s=slotById(r.slot_id);if(s&&PBY[r.person]){const f=fit(r.person,s);const l=[...f.no.map(x=>'⛔ '+x),...f.warn.map(x=>'⚠ '+x)];if(l.length){const w=document.createElement('div');w.className='warnbox';w.style.whiteSpace='pre-line';w.textContent=l.join('\n');t.append(w)}}}
